/**
 * #5258: the write line says "clean" only when a check of the file's kind
 * completed. These rows drive the real producers of `DispatchResult.verdict`
 * (`dispatchLintWithResult`'s two early returns, `dispatchForFile`'s generated
 * short-circuit and coverage rule, `dispatchLintDetailed`) and the per-runner
 * failure matrix over every primary runner of every kind.
 *
 * Recurrence prevented: the 2026-11-04 clean-verdict probe. A missing
 * `unconfirmedStatus` was read as clean, so a TypeScript error under
 * `--no-lsp`, a `build.gradle` (the #5238 Groovy class), a generated file and
 * a kind with no analyzer all read `✓ … clean`.
 */

import * as fs from "node:fs";
import * as path from "node:path";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import {
	clearCoverageNoticeState,
	clearLatencyReports,
	createDispatchContext,
	dispatchForFile,
	RunnerRegistry,
} from "../../../clients/dispatch/dispatcher.js";
import { FactStore } from "../../../clients/dispatch/fact-store.js";
import {
	dispatchLintDetailed,
	dispatchLintWithResult,
} from "../../../clients/dispatch/integration.js";
import {
	type CoverageVerdict,
	NO_ANALYZER_REASON,
	noPrimaryCheckerReason,
	type RunnerGroup,
	type RunnerResult,
} from "../../../clients/dispatch/types.js";
import {
	detectFileKind,
	type FileKind,
	KIND_EXTENSIONS,
	TERRAGRUNT_FILENAMES,
} from "../../../clients/file-kinds.js";
import { getPrimaryDispatchGroup } from "../../../clients/language-policy.js";
import { setupTestEnvironment } from "../test-utils.js";

const flags = (noLsp: boolean) => ({
	getFlag: (flag: string) => flag === "no-lsp" && noLsp,
});

const unchecked = (reason: string): CoverageVerdict => ({
	checked: false,
	reason,
});

describe("every producer of a dispatch result states a verdict (#5258)", () => {
	const env = setupTestEnvironment("pi-lens-verdict-");
	afterEach(() => env.cleanup());

	const write = (name: string, content: string) => {
		const file = path.join(env.tmpDir, name);
		fs.mkdirSync(path.dirname(file), { recursive: true });
		fs.writeFileSync(file, content);
		return file;
	};

	beforeEach(() => {
		clearCoverageNoticeState();
		clearLatencyReports();
	});

	// Producer rows of the #5258 state table. Each reason a file can go
	// unchecked is a row: the call that produces it and the verdict it owes.
	it("a file with no kind: no analyzer handles it", async () => {
		const file = write("notes.zzz", "plain notes\n");
		const result = await dispatchLintWithResult(file, env.tmpDir, flags(false));
		expect(result.verdict).toEqual(unchecked(NO_ANALYZER_REASON));
	});

	it("a kindless file handed straight to the dispatcher is unchecked too (the coverage rule's own no-kind return)", async () => {
		const file = write("notes.zzz", "plain notes\n");
		const ctx = createDispatchContext(
			file,
			env.tmpDir,
			flags(false),
			new FactStore(),
		);
		const result = await dispatchForFile(
			ctx,
			[{ mode: "all", runnerIds: ["lsp"] }],
			new RunnerRegistry(),
		);
		expect(result.verdict).toEqual(unchecked(NO_ANALYZER_REASON));
	});

	it("--no-lsp, a kind whose only primary is the language server: no runner exists (the dispatchLintWithResult groups.length === 0 return)", async () => {
		// Groovy has `lsp` as its only runner, so --no-lsp leaves no group. This
		// is the early return the #5238 review named: it returned before
		// `dispatchForFile` with nothing for the all-clear line to read.
		const file = write("build.gradle", 'plugins {\n  id "java"\n');
		const noLsp = await dispatchLintWithResult(file, env.tmpDir, flags(true));
		expect(noLsp.verdict).toEqual(unchecked(noPrimaryCheckerReason(false)));
		expect(noLsp.verdict).toMatchObject({
			reason: expect.stringContaining("--no-lsp"),
		});
	});

	it("dispatchLintDetailed's empty result is unchecked, not clean", async () => {
		const file = write("notes.zzz", "plain notes\n");
		const { result } = await dispatchLintDetailed(
			file,
			env.tmpDir,
			flags(false),
		);
		expect(result.verdict).toEqual(unchecked("no runner ran for this file"));
	});

	it("a generated file the dispatcher skips by design is unchecked", async () => {
		const file = write(
			"api.generated.ts",
			'// Code generated by protoc. DO NOT EDIT.\nconst n: number = "x";\n',
		);
		const ctx = createDispatchContext(
			file,
			env.tmpDir,
			flags(true),
			new FactStore(),
		);
		const result = await dispatchForFile(
			ctx,
			[{ mode: "all", runnerIds: ["lsp"] }],
			new RunnerRegistry(),
		);
		expect(result.verdict).toEqual(unchecked("generated file (not analyzed)"));
	});

	it("a kind with a primary group none of whose runners ran is unchecked", async () => {
		// Only a linter ran, so no row of the primary group exists. This was the
		// coverage rule's bare `{}`.
		const registry = new RunnerRegistry();
		registry.register({
			id: "eslint",
			appliesTo: ["jsts"],
			priority: 5,
			async run(): Promise<RunnerResult> {
				return { status: "succeeded", diagnostics: [], semantic: "none" };
			},
		});
		const ctx = createDispatchContext(
			path.join(env.tmpDir, "a.ts"),
			env.tmpDir,
			flags(false),
			new FactStore(),
		);
		const result = await dispatchForFile(
			ctx,
			[{ mode: "all", runnerIds: ["eslint"] }],
			registry,
		);
		expect(result.verdict).toEqual(
			unchecked("no primary runner ran for this file"),
		);
	});
});

// One sample path per kind, derived from the registries so a new kind is a new
// row. The test below fails if a kind has no sample (the exclusion is pinned).
function samplePath(kind: FileKind): string | undefined {
	const candidates = [
		...KIND_EXTENSIONS[kind].map((ext) => `sample${ext}`),
		...(kind === "terragrunt" ? TERRAGRUNT_FILENAMES : []),
		...(kind === "groovy" ? ["build.gradle"] : []),
		...(kind === "docker" ? ["Dockerfile"] : []),
		...(kind === "cmake" ? ["CMakeLists.txt"] : []),
	];
	return candidates.find(
		(name) => detectFileKind(path.join("/project", name)) === kind,
	);
}

type FailureMode = {
	name: string;
	run: () => Promise<RunnerResult>;
	timeoutMs?: number;
	/** The runner never answers; the test builds that promise under fake timers. */
	hangs?: true;
};

// The four ways a primary runner fails to answer, each in the form the real
// runners return it (`RunnerResult.failureKind` taxonomy in dispatch/types.ts).
const FAILURE_MODES: FailureMode[] = [
	{
		name: "timeout",
		timeoutMs: 1,
		hangs: true,
		run: async () => ({ status: "skipped", diagnostics: [], semantic: "none" }),
	},
	{
		name: "error",
		run: async () => {
			throw new Error("runner crashed");
		},
	},
	{
		name: "malformed output",
		run: async () => ({
			status: "failed",
			diagnostics: [],
			semantic: "none",
			failureKind: "parser_error",
		}),
	},
	{
		name: "absent binary",
		run: async () => ({ status: "skipped", diagnostics: [], semantic: "none" }),
	},
];

const PRIMARY_ROWS = (Object.keys(KIND_EXTENSIONS) as FileKind[]).flatMap(
	(kind) =>
		[true, false].flatMap((lspEnabled) =>
			(getPrimaryDispatchGroup(kind, lspEnabled)?.runnerIds ?? []).map(
				(runnerId) => ({ kind, lspEnabled, runnerId }),
			),
		),
);

describe("per-runner failure matrix: no primary runner's failure renders clean (#5258)", () => {
	const rows = PRIMARY_ROWS.flatMap((row) => {
		const file = samplePath(row.kind);
		return file === undefined ? [] : [{ ...row, file }];
	});

	beforeEach(() => {
		clearCoverageNoticeState();
		clearLatencyReports();
	});
	afterEach(() => {
		vi.useRealTimers();
	});

	it("drives enough rows that the matrix is not vacuous", () => {
		// Kinds the sample builder cannot name are excluded; that set is pinned
		// empty, so a new kind whose detection needs more than a name fails here.
		const excluded = [
			...new Set(
				PRIMARY_ROWS.filter((row) => samplePath(row.kind) === undefined).map(
					(row) => row.kind,
				),
			),
		];
		expect(excluded).toEqual([]);
		expect(rows.length).toBeGreaterThan(60);
	});

	for (const mode of FAILURE_MODES) {
		it(`${mode.name}: the verdict is unchecked for every primary runner of every kind`, async () => {
			if (mode.timeoutMs !== undefined) vi.useFakeTimers();
			const run = mode.hangs
				? () => new Promise<RunnerResult>(() => {})
				: mode.run;
			const clean: string[] = [];
			for (const row of rows) {
				const registry = new RunnerRegistry();
				registry.register({
					id: row.runnerId,
					appliesTo: [row.kind],
					priority: 5,
					...(mode.timeoutMs !== undefined && { timeoutMs: mode.timeoutMs }),
					run,
				});
				const ctx = createDispatchContext(
					path.join("/project", row.file),
					"/project",
					flags(!row.lspEnabled),
					new FactStore(),
				);
				const group: RunnerGroup = { mode: "all", runnerIds: [row.runnerId] };
				const pending = dispatchForFile(ctx, [group], registry, undefined, {
					dedupeCoverageNotice: false,
				});
				// A runner that never settles is cut by its own timeout: advancing the
				// fake clock past it lets the dispatcher's timeout row land.
				if (mode.timeoutMs !== undefined)
					await vi.advanceTimersByTimeAsync(60_000);
				const result = await pending;
				if (result.verdict.checked)
					clean.push(`${row.kind}/${row.runnerId}/lsp=${row.lspEnabled}`);
			}
			expect(clean).toEqual([]);
		}, 30_000);
	}

	it("control: the same rows read checked when the runner succeeds, naming it", async () => {
		const wrong: string[] = [];
		for (const row of rows) {
			const registry = new RunnerRegistry();
			registry.register({
				id: row.runnerId,
				appliesTo: [row.kind],
				priority: 5,
				async run(): Promise<RunnerResult> {
					return { status: "succeeded", diagnostics: [], semantic: "none" };
				},
			});
			const ctx = createDispatchContext(
				path.join("/project", row.file),
				"/project",
				flags(!row.lspEnabled),
				new FactStore(),
			);
			const result = await dispatchForFile(
				ctx,
				[{ mode: "all", runnerIds: [row.runnerId] }],
				registry,
				undefined,
				{ dedupeCoverageNotice: false },
			);
			if (
				!(
					result.verdict.checked &&
					result.verdict.tier === "primary" &&
					result.verdict.runnerIds.includes(row.runnerId)
				)
			)
				wrong.push(`${row.kind}/${row.runnerId}/lsp=${row.lspEnabled}`);
		}
		expect(wrong).toEqual([]);
	}, 30_000);
});
